function dbStripComments(text){
  return String(text||'').replace(/\/\/[^\n]*/g,'').replace(/\/\*[\s\S]*?\*\//g,'');
}
function dbParse(text){
  var src=dbStripComments(text);
  if(!src.trim()) return { error:'请输入 DBML 内容' };
  var tables=[], refs=[], re=/Table\s+([A-Za-z_][\w."]*)\s*(?:as\s+\w+\s*)?\{([\s\S]*?)\}/gi, m;
  while((m=re.exec(src))!==null){
    var name=m[1].replace(/"/g,''), bodyText=m[2], cols=[], idx=[];
    var lines=bodyText.split(/\n/);
    for(var i=0;i<lines.length;i++){
      var l=lines[i].trim();
      if(!l || /^(indexes|Note)\b/i.test(l) || l==='{' || l==='}') continue;
      var cm=l.match(/^([A-Za-z_][\w]*|"[^"]+")\s+([A-Za-z_][\w]*(?:\([^)]*\))?)\s*(\[[^\]]*\])?/);
      if(!cm) continue;
      var attrs=(cm[3]||'').toLowerCase();
      var col={ name:cm[1].replace(/"/g,''), type:cm[2],
                pk:/\bpk\b|primary key/.test(attrs),
                notNull:/\bnot null\b/.test(attrs) || /\bpk\b/.test(attrs),
                unique:/\bunique\b/.test(attrs),
                increment:/\bincrement\b/.test(attrs),
                def:(function(){ var d=(cm[3]||'').match(/default:\s*([^,\]]+)/i); return d? d[1].trim() : null; })() };
      var rf=(cm[3]||'').match(/ref:\s*([<>-])\s*([\w.]+)\.([\w]+)/i);
      if(rf) refs.push({ from:name, fromCol:col.name, to:rf[2], toCol:rf[3], kind:rf[1] });
      cols.push(col);
    }
    tables.push({ name:name, cols:cols, indexes:idx });
  }
  var rre=/Ref\s*[\w]*\s*:?\s*([\w."]+)\.([\w"]+)\s*([<>-])\s*([\w."]+)\.([\w"]+)/gi, r2;
  while((r2=rre.exec(src))!==null){
    refs.push({ from:r2[1].replace(/"/g,''), fromCol:r2[2].replace(/"/g,''),
                to:r2[4].replace(/"/g,''), toCol:r2[5].replace(/"/g,''), kind:r2[3] });
  }
  if(!tables.length) return { error:'未解析到任何 Table 定义' };
  return { error:null, tables:tables, refs:refs };
}
function dbSqlType(t, dialect){
  var base=String(t).toLowerCase();
  if(dialect==='mysql'){
    if(/^text$/.test(base)) return 'TEXT';
    if(/^bool(ean)?$/.test(base)) return 'TINYINT(1)';
    if(/^timestamp$/.test(base)) return 'DATETIME';
    if(/^uuid$/.test(base)) return 'CHAR(36)';
  } else {
    if(/^int$/.test(base)) return 'integer';
    if(/^bool$/.test(base)) return 'boolean';
  }
  return t;
}
function dbToSql(model, dialect){
  if(!model || model.error) return '';
  dialect = dialect || 'postgres';
  var q = dialect==='mysql' ? '`' : '"';
  var out=[];
  for(var i=0;i<model.tables.length;i++){
    var t=model.tables[i], lines=[];
    for(var j=0;j<t.cols.length;j++){
      var c=t.cols[j], s=q+c.name+q+' '+dbSqlType(c.type, dialect);
      if(c.increment) s += dialect==='mysql' ? ' AUTO_INCREMENT' : ' GENERATED BY DEFAULT AS IDENTITY';
      if(c.notNull) s += ' NOT NULL';
      if(c.unique && !c.pk) s += ' UNIQUE';
      if(c.def!==null && c.def!==undefined) s += ' DEFAULT '+c.def;
      lines.push('  '+s);
    }
    var pks=t.cols.filter(function(c){ return c.pk; }).map(function(c){ return q+c.name+q; });
    if(pks.length) lines.push('  PRIMARY KEY ('+pks.join(', ')+')');
    out.push('CREATE TABLE '+q+t.name+q+' (\n'+lines.join(',\n')+'\n);');
  }
  for(var k=0;k<model.refs.length;k++){
    var r=model.refs[k];
    out.push('ALTER TABLE '+q+r.from+q+' ADD CONSTRAINT '+q+'fk_'+r.from+'_'+r.fromCol+q+
             ' FOREIGN KEY ('+q+r.fromCol+q+') REFERENCES '+q+r.to+q+' ('+q+r.toCol+q+');');
  }
  return out.join('\n\n');
}
function dbStats(model){
  if(!model || model.error) return { tables:0, cols:0, refs:0, pkMissing:[] };
  var cols=0, miss=[];
  for(var i=0;i<model.tables.length;i++){
    cols += model.tables[i].cols.length;
    if(!model.tables[i].cols.some(function(c){ return c.pk; })) miss.push(model.tables[i].name);
  }
  return { tables:model.tables.length, cols:cols, refs:model.refs.length, pkMissing:miss };
}
function dbLint(model){
  if(!model || model.error) return [];
  var out=[], names={};
  for(var i=0;i<model.tables.length;i++){
    var t=model.tables[i];
    if(names[t.name]) out.push('表名重复：'+t.name);
    names[t.name]=1;
    var seen={};
    for(var j=0;j<t.cols.length;j++){
      var c=t.cols[j];
      if(seen[c.name]) out.push(t.name+' 字段重复：'+c.name);
      seen[c.name]=1;
    }
    if(!t.cols.some(function(c){ return c.pk; })) out.push(t.name+' 缺少主键');
  }
  for(var k=0;k<model.refs.length;k++){
    if(!names[model.refs[k].to]) out.push('外键指向未知表：'+model.refs[k].to);
  }
  return out;
}
function dbMermaid(model){
  if(!model || model.error) return '';
  var out=['erDiagram'];
  for(var i=0;i<model.tables.length;i++){
    var t=model.tables[i];
    out.push('  '+t.name+' {');
    for(var j=0;j<t.cols.length;j++) out.push('    '+t.cols[j].type.replace(/[()\s,]/g,'_')+' '+t.cols[j].name);
    out.push('  }');
  }
  for(var k=0;k<model.refs.length;k++){
    var r=model.refs[k];
    out.push('  '+r.to+' ||--o{ '+r.from+' : "'+r.fromCol+'"');
  }
  return out.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { dbStripComments:dbStripComments, dbParse:dbParse, dbSqlType:dbSqlType,
    dbToSql:dbToSql, dbStats:dbStats, dbLint:dbLint, dbMermaid:dbMermaid };
}
if (typeof window !== 'undefined') {
  window.DbmlForgePure = { dbStripComments:dbStripComments, dbParse:dbParse, dbSqlType:dbSqlType,
    dbToSql:dbToSql, dbStats:dbStats, dbLint:dbLint, dbMermaid:dbMermaid };
}
